 async Task ExportCharacterSelected(bool all)
 {
  if(UseBatches&&(!int.TryParse(batchSize.Text,out var batchCount)||batchCount<1||batchCount>128))throw new Exception("每批动作数需为 1–128");var id=Selected();if(!int.TryParse(limit.Text,out var n)||n<0)throw new Exception("数量上限需为非负整数");
  bool selected=!all&&clipSource==CurrentClipSource();
  if(clipChoices.Count>0&&clipSource!=CurrentClipSource())throw new Exception("动作列表不属于当前角色/动画来源，请重新加载当前角色动作");
  if(selected&&!clipChoices.Any(c=>c.Export))throw new Exception("没有勾选导出动作");
  if(clipChoices.Any(c=>c.InPlace)&&RootAxes().Length==0)throw new Exception("请勾选去除根运动的轴");
  if(clipChoices.Any(c=>c.InPlace)&&blender.IsChecked!=true)throw new Exception("去根运动需要勾选“生成 Blender 工程”");
  var job=Job(id);var arguments=new List<string>{"extract","--root",Value("game"),"--character",id,"--animation",animation.SelectedItem as string??id,"--limit",(all||selected?0:n).ToString(),"--out",job};
  if(selected){var list=Path.Combine(job,"selected_actions.json");File.WriteAllText(list,JsonSerializer.Serialize(clipChoices.Where(c=>c.Export).Select(c=>c.Name)));arguments.AddRange(new[]{"--clip-list",list});}
  await Exec(Worker(),arguments.ToArray());if(id=="c0000"&&equip.IsChecked==true)await Python("prepare_equipment.py","--package",job,"--worker",Worker(),"--left",left.Text??"73000");await Metadata(job);SetNpcWeaponMode(job);
  try{await Blend(job);if(audio.IsChecked==true)await Python("audio_extract.py","--package",job,"--root",Value("game"),"--dsas",Value("dsas"),"--ffmpeg",Value("ffmpeg"),"--language","jajp","--cache",activeTaskCache??Value("cache"),"--render");}
  catch(Exception e){File.WriteAllText(Path.Combine(job,"execution_validation.json"),JsonSerializer.Serialize(new{passed=false,error=e.Message}));throw;}finally{Summarize(job);}
  if(cs2AfterExport.IsChecked==true){fields["cs2_package"].Text=job;cs2All.IsChecked=true;SaveSettings();await ConvertCs2();}
 }
