 async Task RepairExisting(){var job=await PickExisting();var package=JsonNode.Parse(File.ReadAllText(Path.Combine(job,"package.json")))!;var npc=npcId.Text?.Trim();if(string.IsNullOrEmpty(npc))npc=package["npcAppearance"]?["selected"]?["id"]?.ToString()??"";await Exec(Worker(),"metadata","--root",Value("game"),"--package",job,"--dsas",Value("dsas"),"--npc",npc);SetNpcWeaponMode(job);foreach(var script in new[]{"repair_appearance.py","verify_saved.py","verify_appearance.py"})await Exec(Value("blender"),"--background","--factory-startup","--disable-autoexec","--threads","4","--python-exit-code","1","--python",Path.Combine(home,"scripts",script),"--",job);Summarize(job);}
