 void Summarize(string job){var reports=new[]{"blend_batches.json","helper_visibility_report.json","animation_endpoint_report.json","sampling_report.json","action_trim_report.json","hierarchy_report.json","bone_cleanup.json","root_motion_report.json","execution_validation.json","appearance_validation.json","blender_validation.json","saved_validation.json","audio/audio_report.json","texture_conversion.json"}.Where(f=>File.Exists(Path.Combine(job,f))).ToDictionary(f=>f,f=>JsonNode.Parse(File.ReadAllText(Path.Combine(job,f))));var package=JsonNode.Parse(File.ReadAllText(Path.Combine(job,"package.json")))!;var native=new JsonObject{["issues"]=package["issues"]?.DeepClone(),["missingTextures"]=package["missingTextures"]?.DeepClone()};reports["native_package"]=native;bool fail=reports.Values.Any(j=>j?["passed"]?.GetValue<bool>()==false||(j?["errors"] as JsonArray)?.Count>0)||(native["issues"] as JsonArray)?.Count>0||(native["missingTextures"] as JsonArray)?.Count>0;if(fail)taskReportsPassed=false;status.Text=fail?"已导出，报告存在缺失或未通过项":"导出完成 · 检查报告中的验证范围";File.WriteAllText(Path.Combine(job,"job_report.json"),JsonSerializer.Serialize(new{status=status.Text,reports},new JsonSerializerOptions{WriteIndented=true}));Log(status.Text+" → "+job);}
